CREATE TABLE `apps` (`id` varchar(36) NOT NULL, `app_key` varchar(48) NOT NULL, `slug` varchar(63) NOT NULL, `name` varchar(200) NOT NULL, `status` varchar(16) NOT NULL, `config_version` bigint NOT NULL, `created_at` bigint NOT NULL, `require_mfa` smallint NOT NULL DEFAULT 0, `issuer` varchar(512) NOT NULL DEFAULT "", `authentication_policy` varchar(1024) NOT NULL DEFAULT "{\"registration_enabled\":true,\"password_login_enabled\":true,\"email_otp_enabled\":true,\"phone_otp_enabled\":true,\"federation_enabled\":true,\"external_registration_enabled\":true,\"passkey_enabled\":false}", `key_epoch` bigint NOT NULL DEFAULT 1, `resource_limits` varchar(1024) NOT NULL DEFAULT "{\"http_concurrency\":256,\"kdf_concurrency\":2,\"db_concurrency\":32,\"requests_per_second\":20000,\"email_challenges_per_hour\":100000,\"sms_challenges_per_hour\":10000}", PRIMARY KEY (`id`), UNIQUE INDEX `app_key` (`app_key`), UNIQUE INDEX `slug` (`slug`), CONSTRAINT `apps_status_recovery_check` CHECK (`status` in (_utf8mb4'active',_utf8mb4'suspended',_utf8mb4'quarantined'))) CHARSET utf8mb4 COLLATE utf8mb4_bin ENGINE InnoDB;
CREATE TABLE `audit_events` (`id` varchar(36) NOT NULL, `app_id` varchar(36) NOT NULL, `created_at` bigint NOT NULL, `payload` longblob NOT NULL, PRIMARY KEY (`app_id`, `id`), INDEX `audit_events_created_at_id_idx` (`app_id`, `created_at`, `id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin ENGINE InnoDB;
