CREATE TABLE `users` (`id` varchar(36) NOT NULL, `app_id` varchar(36) NOT NULL, `status` varchar(16) NOT NULL, `session_epoch` bigint NOT NULL, `created_at` bigint NOT NULL, `payload` longblob NOT NULL, PRIMARY KEY (`app_id`, `id`), INDEX `users_status_id_idx` (`app_id`, `status`, `id`), CONSTRAINT `users_ibfk_1` FOREIGN KEY (`app_id`) REFERENCES `apps` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION) CHARSET utf8mb4 COLLATE utf8mb4_bin ENGINE InnoDB;
