CREATE TABLE `agents` (`id` varchar(36) NOT NULL, `app_id` varchar(36) NOT NULL, `client_id` varchar(64) NOT NULL, `status` varchar(16) NOT NULL, `config_version` bigint NOT NULL, `payload` longblob NOT NULL, PRIMARY KEY (`app_id`, `id`), UNIQUE INDEX `app_id` (`app_id`, `client_id`), CONSTRAINT `agents_ibfk_1` FOREIGN KEY (`app_id`, `client_id`) REFERENCES `clients` (`app_id`, `client_id`) ON UPDATE NO ACTION ON DELETE NO ACTION) CHARSET utf8mb4 COLLATE utf8mb4_bin ENGINE InnoDB;
